begin;
create table if not exists public.mme_ap_bills(bill_id uuid primary key default gen_random_uuid(),invoice_id uuid references public.mme_vendor_invoices(invoice_id),vendor_id uuid not null references public.mme_vendors(vendor_id),bill_number text not null,bill_date date not null,due_date date,amount numeric(14,2) not null check(amount>0),currency text not null default 'USD',status text not null default 'pending_review' check(status in ('pending_review','approved','scheduled','paid','disputed','void')),description text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(vendor_id,bill_number));
create table if not exists public.mme_ap_approval_rules(rule_id uuid primary key default gen_random_uuid(),rule_name text not null,minimum_amount numeric(14,2) not null default 0 check(minimum_amount>=0),maximum_amount numeric(14,2) check(maximum_amount is null or maximum_amount>=minimum_amount),required_approvals integer not null default 1 check(required_approvals between 1 and 5),required_role text not null,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.mme_ap_approvals(approval_id uuid primary key default gen_random_uuid(),bill_id uuid not null references public.mme_ap_bills(bill_id),approver_auth_user_id uuid not null,decision text not null check(decision in ('approved','rejected')),role_at_decision text not null,notes text,created_at timestamptz not null default now(),unique(bill_id,approver_auth_user_id));
create table if not exists public.mme_ap_payment_proposals(proposal_id uuid primary key default gen_random_uuid(),proposal_reference text not null unique,bill_id uuid not null references public.mme_ap_bills(bill_id),vendor_id uuid not null references public.mme_vendors(vendor_id),amount numeric(14,2) not null check(amount>0),payment_method text not null check(payment_method in ('check','ach')),scheduled_date date not null,status text not null default 'draft' check(status in ('draft','approved','exported','void','reconciled')),external_payment_reference text,created_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_ap_positive_pay_items(item_id uuid primary key default gen_random_uuid(),proposal_id uuid not null references public.mme_ap_payment_proposals(proposal_id),check_number text not null,check_date date not null,payee_name text not null,amount numeric(14,2) not null check(amount>0),account_last4 text not null check(account_last4 ~ '^[0-9]{4}$'),status text not null default 'pending_export' check(status in ('pending_export','exported','matched','exception','void')),created_at timestamptz not null default now(),unique(check_number,account_last4));
create table if not exists public.mme_ap_bank_transactions(bank_transaction_id uuid primary key default gen_random_uuid(),bank_reference text not null unique,transaction_date date not null,description text,amount numeric(14,2) not null,transaction_type text not null check(transaction_type in ('debit','credit')),matched_proposal_id uuid references public.mme_ap_payment_proposals(proposal_id),reconciliation_status text not null default 'unmatched' check(reconciliation_status in ('unmatched','matched','exception','ignored')),imported_by_auth_user_id uuid not null,created_at timestamptz not null default now());
create table if not exists public.mme_ap_audit_events(event_id uuid primary key default gen_random_uuid(),actor_auth_user_id uuid not null,action text not null,entity_type text not null,entity_id uuid,details jsonb not null default '{}',request_id uuid not null,created_at timestamptz not null default now());
create index if not exists mme_ap_bills_due_idx on public.mme_ap_bills(status,due_date);
create index if not exists mme_ap_proposals_date_idx on public.mme_ap_payment_proposals(status,scheduled_date);
create index if not exists mme_ap_bank_reconcile_idx on public.mme_ap_bank_transactions(reconciliation_status,transaction_date);
create or replace function public.mme_ap_approve_bill(p_bill_id uuid,p_actor uuid,p_role text,p_notes text) returns uuid language plpgsql security definer set search_path=public as $$ declare v_bill public.mme_ap_bills%rowtype;v_rule public.mme_ap_approval_rules%rowtype;v_count integer;begin select * into v_bill from public.mme_ap_bills where bill_id=p_bill_id for update;if not found then raise exception 'bill_not_found';end if;if v_bill.status not in ('pending_review','approved') then raise exception 'bill_not_reviewable';end if;select * into v_rule from public.mme_ap_approval_rules where active and minimum_amount<=v_bill.amount and (maximum_amount is null or maximum_amount>=v_bill.amount) and required_role=p_role order by minimum_amount desc limit 1;if not found then raise exception 'no_matching_approval_rule';end if;insert into public.mme_ap_approvals(bill_id,approver_auth_user_id,decision,role_at_decision,notes) values(p_bill_id,p_actor,'approved',p_role,p_notes) on conflict(bill_id,approver_auth_user_id) do nothing;select count(distinct approver_auth_user_id) into v_count from public.mme_ap_approvals where bill_id=p_bill_id and decision='approved';if v_count>=v_rule.required_approvals then update public.mme_ap_bills set status='approved',updated_at=now() where bill_id=p_bill_id;end if;return p_bill_id;end $$;
create or replace function public.mme_ap_schedule_payment(p_bill_id uuid,p_reference text,p_method text,p_date date,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_bill public.mme_ap_bills%rowtype;v_id uuid;begin select * into v_bill from public.mme_ap_bills where bill_id=p_bill_id for update;if not found then raise exception 'bill_not_found';end if;if v_bill.status<>'approved' then raise exception 'bill_not_approved';end if;if p_method not in ('check','ach') then raise exception 'invalid_payment_method';end if;if p_date<current_date then raise exception 'payment_date_in_past';end if;if exists(select 1 from public.mme_ap_payment_proposals where bill_id=p_bill_id and status not in ('void')) then raise exception 'payment_already_proposed';end if;insert into public.mme_ap_payment_proposals(proposal_reference,bill_id,vendor_id,amount,payment_method,scheduled_date,created_by_auth_user_id) values(p_reference,p_bill_id,v_bill.vendor_id,v_bill.amount,p_method,p_date,p_actor) returning proposal_id into v_id;update public.mme_ap_bills set status='scheduled',updated_at=now() where bill_id=p_bill_id;return v_id;end $$;
create or replace function public.mme_ap_match_bank_transaction(p_transaction_id uuid,p_proposal_id uuid,p_actor uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare v_tx public.mme_ap_bank_transactions%rowtype;v_p public.mme_ap_payment_proposals%rowtype;begin select * into v_tx from public.mme_ap_bank_transactions where bank_transaction_id=p_transaction_id for update;if not found then raise exception 'bank_transaction_not_found';end if;select * into v_p from public.mme_ap_payment_proposals where proposal_id=p_proposal_id for update;if not found then raise exception 'payment_proposal_not_found';end if;if v_tx.reconciliation_status<>'unmatched' or v_p.status not in ('approved','exported') then raise exception 'transaction_not_matchable';end if;if v_tx.transaction_type<>'debit' or abs(v_tx.amount-v_p.amount)>0.01 then raise exception 'amount_or_type_mismatch';end if;update public.mme_ap_bank_transactions set matched_proposal_id=p_proposal_id,reconciliation_status='matched' where bank_transaction_id=p_transaction_id;update public.mme_ap_payment_proposals set status='reconciled' where proposal_id=p_proposal_id;update public.mme_ap_bills set status='paid',updated_at=now() where bill_id=v_p.bill_id;return p_transaction_id;end $$;
alter table public.mme_ap_bills enable row level security;alter table public.mme_ap_approval_rules enable row level security;alter table public.mme_ap_approvals enable row level security;alter table public.mme_ap_payment_proposals enable row level security;alter table public.mme_ap_positive_pay_items enable row level security;alter table public.mme_ap_bank_transactions enable row level security;alter table public.mme_ap_audit_events enable row level security;
do $$ declare t text;begin foreach t in array array['mme_ap_bills','mme_ap_approval_rules','mme_ap_approvals','mme_ap_payment_proposals','mme_ap_positive_pay_items','mme_ap_bank_transactions','mme_ap_audit_events'] loop execute format('revoke all on public.%I from public,anon,authenticated',t);execute format('grant all on public.%I to service_role',t);end loop;end $$;
revoke all on function public.mme_ap_approve_bill(uuid,uuid,text,text) from public,anon,authenticated;revoke all on function public.mme_ap_schedule_payment(uuid,text,text,date,uuid) from public,anon,authenticated;revoke all on function public.mme_ap_match_bank_transaction(uuid,uuid,uuid) from public,anon,authenticated;grant execute on function public.mme_ap_approve_bill(uuid,uuid,text,text) to service_role;grant execute on function public.mme_ap_schedule_payment(uuid,text,text,date,uuid) to service_role;grant execute on function public.mme_ap_match_bank_transaction(uuid,uuid,uuid) to service_role;
commit;